// ── PWA: Wiring (idempotent, one-time) ──────────────────────────────────────
function _pwaWire() {
  if (_pwaWired) return;
  _pwaWired = true;

  const bind = (id, fn) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('click', fn);
  };
  bind('installHelpBtn',   pwaOpenHelp);
  bind('pwaPopupAdd',      pwaPopupConfirm);
  bind('pwaPopupLater',    pwaPopupLater);
  bind('pwaPopupClose',    pwaPopupClose);
  bind('pwaPopupBackdrop', pwaPopupLater);

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      if (_pwaPopupShown) pwaPopupLater();
      return;
    }
    if (e.key !== 'Tab' || !_pwaPopupShown) return;
    const popup = document.getElementById('pwaPopup');
    if (!popup) return;
    const focusable = Array.from(popup.querySelectorAll(
      'button:not([disabled]), [href], input:not([disabled]), [tabindex]:not([tabindex="-1"])'
    )).filter(el => !el.hasAttribute('inert') && el.offsetParent !== null);
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  });
}
